// Verifies Kairo's HMAC signature on test calls and normalises the payload.
// Requires: NODE_FUNCTION_ALLOW_BUILTIN=crypto and env var KAIRO_WEBHOOK_SECRET on the n8n host.
const crypto = require('crypto');
const item = $input.first().json;
const headers = item.headers || {};
const body = item.body || {};
const isTest = headers['x-kairo-test'] === 'true' || body.test === true;
if (isTest) {
  const ts = headers['x-kairo-timestamp'];
  const sig = (headers['x-kairo-signature'] || '').replace('sha256=', '');
  const expected = crypto.createHmac('sha256', $env.KAIRO_WEBHOOK_SECRET).update(`${ts}.${JSON.stringify(body)}`).digest('hex');
  if (!ts || Math.abs(Date.now() / 1000 - Number(ts)) > 300 || sig !== expected) throw new Error('Invalid Kairo test signature');
}
// Map your voice platform's end-of-call payload (Vapi, Retell, etc.) to a common shape.
// Verify the platform's own webhook secret header here in production.
const m = body.message || body;
const call = isTest ? { id: 'TEST', customerNumber: '+447700900000', summary: 'Test call: caller asked about opening hours', structured: { name: 'Test Caller', wants_booking: false } } : {
  id: m.call?.id || m.call_id, customerNumber: m.call?.customer?.number || m.from_number, summary: m.analysis?.summary || m.call_analysis?.call_summary || '', structured: m.analysis?.structuredData || m.call_analysis?.custom_analysis_data || {} };
return [{ json: { ...call, isTest } }];

// Builds a signed activity event for the Kairo platform.
const crypto = require('crypto');
const d = $input.first().json;
const event = {
  automation_id: $env.KAIRO_AUTOMATION_ID_RECEPTIONIST,
  event_type: 'call.answered',
  summary: `AI receptionist: ${d.summary || 'call handled'}`.slice(0, 480),
  test: d.isTest === true,
  external_event_id: `voice-${d.id}`,
  lead: { name: d.structured?.name, phone: d.customerNumber, source: 'ai_receptionist', enquiry: d.summary },
};
const body = JSON.stringify(event);
const ts = Math.floor(Date.now() / 1000).toString();
const sig = crypto.createHmac('sha256', $env.KAIRO_WEBHOOK_SECRET).update(`${ts}.${body}`).digest('hex');
return [{ json: { body, ts, sig, isTest: d.isTest === true, ...d } }];
